package com.shms.controller;
import com.shms.entity.User;import com.shms.repository.AppointmentRepository;import com.shms.repository.InvoiceRepository;import com.shms.repository.PatientRepository;import jakarta.servlet.http.HttpSession;import org.springframework.stereotype.Controller;import org.springframework.ui.Model;import org.springframework.web.bind.annotation.GetMapping;
@Controller public class PatientDashboardController{private final PatientRepository patients;private final AppointmentRepository appointments;private final InvoiceRepository bills;public PatientDashboardController(PatientRepository p,AppointmentRepository a,InvoiceRepository b){patients=p;appointments=a;bills=b;}@GetMapping("/patient-dashboard")public String dashboard(HttpSession s,Model m){Object o=s.getAttribute("currentUser");if(!(o instanceof User u))return "redirect:/login";var p=patients.findByUserId(u.getId()).orElse(null);if(p==null)return "redirect:/login";m.addAttribute("patient",p);m.addAttribute("appointments",appointments.findByPatientId(p.getId()));m.addAttribute("bills",bills.findByPatient(p));return "patient-dashboard";}}
